#!/usr/bin/env python3
"""
GitHub API client with rate limit handling and retry logic.
"""
import time
import requests
from typing import Dict, Optional


class GitHubClient:
    BASE_URL = "https://api.github.com"

    def __init__(self, pat: str):
        self.session = requests.Session()
        self.session.headers.update({
            "Authorization": f"Bearer {pat}",
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
        })

    def _request(self, method: str, path: str, **kwargs) -> requests.Response:
        url = f"{self.BASE_URL}{path}"
        response = self.session.request(method, url, **kwargs)

        if response.status_code == 429:
            retry_after = int(response.headers.get("Retry-After", 60))
            print(f"  Rate limited — waiting {retry_after}s...")
            time.sleep(retry_after)
            return self._request(method, path, **kwargs)

        return response

    def get(self, path: str, params: Dict = None) -> Dict:
        r = self._request("GET", path, params=params)
        r.raise_for_status()
        return r.json()

    def post(self, path: str, json: Dict = None) -> requests.Response:
        return self._request("POST", path, json=json)

    def put(self, path: str, json: Dict = None) -> Dict:
        r = self._request("PUT", path, json=json)
        r.raise_for_status()
        return r.json()

    def download_zip(self, path: str) -> bytes:
        """Download a ZIP artifact, following redirects."""
        url = f"{self.BASE_URL}{path}"
        r = self.session.get(url, allow_redirects=True)
        r.raise_for_status()
        return r.content

    # ── Repo ──────────────────────────────────────────────

    def get_repo(self, owner: str, repo: str) -> Dict:
        return self.get(f"/repos/{owner}/{repo}")

    def get_languages(self, owner: str, repo: str) -> Dict:
        return self.get(f"/repos/{owner}/{repo}/languages")

    def get_file(self, owner: str, repo: str, path: str) -> Optional[Dict]:
        try:
            return self.get(f"/repos/{owner}/{repo}/contents/{path}")
        except Exception:
            return None

    def commit_file(self, owner: str, repo: str, path: str,
                    content_b64: str, message: str,
                    sha: Optional[str] = None) -> Dict:
        body = {"message": message, "content": content_b64}
        if sha:
            body["sha"] = sha
        return self.put(f"/repos/{owner}/{repo}/contents/{path}", json=body)

    # ── Actions ───────────────────────────────────────────

    def trigger_workflow(self, owner: str, repo: str,
                         workflow_file: str, ref: str,
                         inputs: Dict = None) -> bool:
        body = {"ref": ref}
        if inputs:
            body["inputs"] = inputs
        r = self.post(
            f"/repos/{owner}/{repo}/actions/workflows/{workflow_file}/dispatches",
            json=body,
        )
        return r.status_code == 204

    def get_workflow_runs(self, owner: str, repo: str,
                          event: str = None) -> Dict:
        params = {}
        if event:
            params["event"] = event
        return self.get(f"/repos/{owner}/{repo}/actions/runs", params=params)

    def get_run(self, owner: str, repo: str, run_id: int) -> Dict:
        return self.get(f"/repos/{owner}/{repo}/actions/runs/{run_id}")

    def get_run_artifacts(self, owner: str, repo: str, run_id: int) -> Dict:
        return self.get(f"/repos/{owner}/{repo}/actions/runs/{run_id}/artifacts")

    def download_artifact(self, owner: str, repo: str,
                          artifact_id: int) -> bytes:
        return self.download_zip(
            f"/repos/{owner}/{repo}/actions/artifacts/{artifact_id}/zip"
        )

#!/usr/bin/env python3
import os
import json
import argparse
from pathlib import Path

# Tree-sitter setup
import tree_sitter
try:
    import tree_sitter_python
    import tree_sitter_javascript
    import tree_sitter_typescript
    import tree_sitter_java
    import tree_sitter_go
    import tree_sitter_ruby
except ImportError:
    print("Warning: Some tree-sitter grammars not installed.")

# Language mapping
LANG_MAP = {
    ".py": ("python", tree_sitter_python),
    ".js": ("javascript", tree_sitter_javascript),
    ".jsx": ("javascript", tree_sitter_javascript),
    ".ts": ("typescript", tree_sitter_typescript),
    ".tsx": ("tsx", tree_sitter_typescript),
    ".java": ("java", tree_sitter_java),
    ".go": ("go", tree_sitter_go),
    ".rb": ("ruby", tree_sitter_ruby)
}

def get_parser(ext):
    if ext not in LANG_MAP:
        return None, None

    lang_name, module = LANG_MAP[ext]
    try:
        # tree-sitter v0.22.0+ API
        language = tree_sitter.Language(module.language())
        parser = tree_sitter.Parser(language)
        return lang_name, parser
    except AttributeError:
        # Older tree-sitter API fallback
        try:
             language = tree_sitter.Language(module.language(), lang_name)
             parser = tree_sitter.Parser()
             parser.set_language(language)
             return lang_name, parser
        except Exception as e:
             print(f"Failed to load parser for {ext}: {e}")
             return None, None
    except Exception as e:
        print(f"Failed to load parser for {ext}: {e}")
        return None, None

def extract_python_info(node, source_bytes):
    funcs = []
    classes = []
    imports = []

    def traverse(n):
        if n.type == 'function_definition':
            name_node = n.child_by_field_name('name')
            if name_node:
                funcs.append({
                    "name": source_bytes[name_node.start_byte:name_node.end_byte].decode('utf8', 'ignore'),
                    "line_start": n.start_point[0] + 1,
                    "line_end": n.end_point[0] + 1
                })
        elif n.type == 'class_definition':
            name_node = n.child_by_field_name('name')
            if name_node:
                classes.append({
                    "name": source_bytes[name_node.start_byte:name_node.end_byte].decode('utf8', 'ignore'),
                    "line_start": n.start_point[0] + 1,
                    "line_end": n.end_point[0] + 1
                })
        elif n.type in ('import_statement', 'import_from_statement'):
            imports.append(source_bytes[n.start_byte:n.end_byte].decode('utf8', 'ignore'))

        for child in n.children:
            traverse(child)

    traverse(node)
    return funcs, classes, imports

def extract_js_ts_info(node, source_bytes):
    funcs = []
    classes = []
    imports = []

    def traverse(n):
        if n.type in ('function_declaration', 'method_definition', 'arrow_function'):
            name_node = n.child_by_field_name('name')
            if name_node:
                funcs.append({
                    "name": source_bytes[name_node.start_byte:name_node.end_byte].decode('utf8', 'ignore'),
                    "line_start": n.start_point[0] + 1,
                    "line_end": n.end_point[0] + 1
                })
        elif n.type == 'class_declaration':
            name_node = n.child_by_field_name('name')
            if name_node:
                classes.append({
                    "name": source_bytes[name_node.start_byte:name_node.end_byte].decode('utf8', 'ignore'),
                    "line_start": n.start_point[0] + 1,
                    "line_end": n.end_point[0] + 1
                })
        elif n.type == 'import_statement':
            imports.append(source_bytes[n.start_byte:n.end_byte].decode('utf8', 'ignore'))

        for child in n.children:
            traverse(child)

    traverse(node)
    return funcs, classes, imports

def extract_java_info(node, source_bytes):
    funcs = []
    classes = []
    imports = []

    def traverse(n):
        if n.type == 'method_declaration':
            name_node = n.child_by_field_name('name')
            if name_node:
                funcs.append({
                    "name": source_bytes[name_node.start_byte:name_node.end_byte].decode('utf8', 'ignore'),
                    "line_start": n.start_point[0] + 1,
                    "line_end": n.end_point[0] + 1
                })
        elif n.type == 'class_declaration':
            name_node = n.child_by_field_name('name')
            if name_node:
                classes.append({
                    "name": source_bytes[name_node.start_byte:name_node.end_byte].decode('utf8', 'ignore'),
                    "line_start": n.start_point[0] + 1,
                    "line_end": n.end_point[0] + 1
                })
        elif n.type == 'import_declaration':
            imports.append(source_bytes[n.start_byte:n.end_byte].decode('utf8', 'ignore'))

        for child in n.children:
            traverse(child)

    traverse(node)
    return funcs, classes, imports


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--output', required=True, help="Output JSON file path")
    args = parser.parse_args()

    results = {}

    for root, _, files in os.walk('.'):
        if '.git' in root:
            continue

        for file in files:
            path = Path(root) / file
            ext = path.suffix

            lang_name, ts_parser = get_parser(ext)
            if not ts_parser:
                continue

            try:
                with open(path, 'rb') as f:
                    source_bytes = f.read()
            except Exception as e:
                print(f"Skipping {path}: {e}")
                continue

            tree = ts_parser.parse(source_bytes)

            funcs, classes, imports = [], [], []
            if lang_name == "python":
                funcs, classes, imports = extract_python_info(tree.root_node, source_bytes)
            elif lang_name in ("javascript", "typescript", "tsx"):
                funcs, classes, imports = extract_js_ts_info(tree.root_node, source_bytes)
            elif lang_name == "java":
                funcs, classes, imports = extract_java_info(tree.root_node, source_bytes)
            # Add other language extractors as needed

            # Use relative path as key (e.g. src/main.py)
            rel_path = str(path.relative_to('.')).replace('\\', '/')
            results[rel_path] = {
                "language": lang_name,
                "ast": {
                    "functions": funcs,
                    "classes": classes,
                    "imports": imports
                },
                "metrics": {
                    "lines_of_code": len(source_bytes.splitlines()),
                    "function_count": len(funcs),
                    "class_count": len(classes),
                    "import_count": len(imports)
                }
            }

    with open(args.output, 'w') as f:
        json.dump(results, f, indent=2)
    print(f"Extracted AST for {len(results)} files to {args.output}")

if __name__ == "__main__":
    main()

import io
import zipfile
import json
from typing import Dict, Any, List
from github_client import GitHubClient

class ArtifactDownloader:
    def __init__(self, client: GitHubClient):
        self.client = client

    def fetch_artifacts(self, owner: str, repo: str, run_id: int) -> Dict[str, Any]:
        """Download and extract AST and SARIF JSONs from artifacts in memory."""
        print(f"Fetching artifacts for run {run_id}...")
        artifacts_info = self.client.get_run_artifacts(owner, repo, run_id)

        ast_data = {}
        sarif_data = []

        for artifact in artifacts_info.get("artifacts", []):
            name = artifact["name"]
            if name == "ast-results":
                print("  Downloading AST artifact...")
                zip_bytes = self.client.download_artifact(owner, repo, artifact["id"])
                ast_data = self._extract_json_from_zip(zip_bytes, "ast.json")
            elif name == "codeql-results":
                print("  Downloading CodeQL SARIF artifact...")
                zip_bytes = self.client.download_artifact(owner, repo, artifact["id"])
                sarif_data.extend(self._extract_all_sarifs_from_zip(zip_bytes))

        return {
            "ast": ast_data,
            "sarif": sarif_data
        }

    def _extract_json_from_zip(self, zip_bytes: bytes, filename: str) -> Dict:
        try:
            with zipfile.ZipFile(io.BytesIO(zip_bytes)) as z:
                if filename in z.namelist():
                    with z.open(filename) as f:
                        return json.load(f)
        except Exception as e:
            print(f"  Error extracting {filename}: {e}")
        return {}

    def _extract_all_sarifs_from_zip(self, zip_bytes: bytes) -> List[Dict]:
        sarifs = []
        try:
            with zipfile.ZipFile(io.BytesIO(zip_bytes)) as z:
                for name in z.namelist():
                    if name.endswith(".sarif"):
                        with z.open(name) as f:
                            sarifs.append(json.load(f))
        except Exception as e:
            print(f"  Error extracting SARIFs: {e}")
        return sarifs

import json
from typing import Dict, List, Any
from datetime import datetime

class KBMerger:
    @staticmethod
    def merge(repo: str, ast_data: Dict[str, Any], sarif_data_list: List[Dict]) -> Dict[str, Any]:
        """Merge AST data and SARIF findings into the final KB format."""
        kb = {
            "repo": repo,
            "scanned_at": datetime.utcnow().isoformat() + "Z",
            "summary": {
                "total_files": len(ast_data),
                "total_functions": 0,
                "total_classes": 0,
                "total_vulnerabilities": 0,
                "languages": list(set(d.get("language") for d in ast_data.values()))
            },
            "files": []
        }

        # Initialize files map with AST data
        files_map = {}
        for path, data in ast_data.items():
            files_map[path] = {
                "path": path,
                "language": data.get("language"),
                "metrics": data.get("metrics", {}),
                "ast": data.get("ast", {}),
                "vulnerabilities": []
            }

            kb["summary"]["total_functions"] += data.get("metrics", {}).get("function_count", 0)
            kb["summary"]["total_classes"] += data.get("metrics", {}).get("class_count", 0)

        # Process SARIF data
        for sarif in sarif_data_list:
            for run in sarif.get("runs", []):
                for result in run.get("results", []):
                    rule_id = result.get("ruleId")
                    message = result.get("message", {}).get("text")
                    level = result.get("level", "warning")

                    # Rule metadata
                    rule_meta = {}
                    rule_index = result.get("ruleIndex", -1)
                    if rule_index >= 0:
                        try:
                            rule_meta = run["tool"]["driver"]["rules"][rule_index]
                        except IndexError:
                            pass

                    cwe = ""
                    if "properties" in rule_meta and "tags" in rule_meta["properties"]:
                        cwes = [t for t in rule_meta["properties"]["tags"] if "external/cwe/" in t]
                        if cwes:
                            cwe = cwes[0].split("/")[-1]

                    for location in result.get("locations", []):
                        phys_loc = location.get("physicalLocation", {})
                        art_loc = phys_loc.get("artifactLocation", {})
                        uri = art_loc.get("uri")

                        if uri:
                            # Normalize URI format
                            uri = uri.replace("\\", "/")
                            if uri.startswith("/"):
                                uri = uri[1:]

                            vuln = {
                                "rule_id": rule_id,
                                "level": level,
                                "cwe": cwe,
                                "message": message,
                                "line_start": phys_loc.get("region", {}).get("startLine"),
                                "line_end": phys_loc.get("region", {}).get("endLine")
                            }

                            if uri not in files_map:
                                files_map[uri] = {
                                    "path": uri,
                                    "ast": {},
                                    "vulnerabilities": []
                                }

                            files_map[uri]["vulnerabilities"].append(vuln)
                            kb["summary"]["total_vulnerabilities"] += 1

        kb["files"] = list(files_map.values())
        return kb

